styles:
/* Aylık Sayım Sonucu — modern detay sayfası */
.ass-page {
  --ass-primary: #4557a3;
  --ass-primary-mid: #586495;
  --ass-accent: #5b6fd6;
  --ass-muted: #94a3b8;
  --ass-label: #64748b;
  --ass-text: #1e293b;
  --ass-border: #e2e8f0;
  --ass-surface: #ffffff;
  --ass-soft: #f8fafc;
  --ass-shadow: 0 4px 24px rgba(69, 87, 163, 0.08);
  --ass-radius: 16px;
  display: flex;
  flex-direction: column;
  width: 100%;
  max-width: 100%;
  min-height: 100%;
  margin: 0;
  padding: 1.25rem 1rem 2.5rem;
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  color: var(--ass-text);
  background: linear-gradient(180deg, #f8fafc 0%, #eef2ff 100%);
  box-sizing: border-box;
}

@media (min-width: 768px) {
  .ass-page {
    padding: 1.5rem 1.5rem 2.75rem;
  }
}

@media (min-width: 1200px) {
  .ass-page {
    padding: 1.75rem 2rem 3rem;
  }
}

.ass-page *,
.ass-page *::before,
.ass-page *::after {
  box-sizing: border-box;
}

/* Toolbar */
.ass-page .ass__toolbar {
  order: -20;
  flex: 0 0 auto;
  width: 100% !important;
  max-width: 100% !important;
  margin: 0 0 1rem 0 !important;
  padding: 0 !important;
}

.ass-page .ass__toolbar > .row,
.ass-page .ass__toolbar .row {
  display: flex !important;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 0.65rem;
  width: 100% !important;
  margin: 0 !important;
}

.ass-page .ass__toolbar .col,
.ass-page .ass__toolbar [class*='col-'] {
  flex: 0 1 auto;
  width: auto !important;
  max-width: none;
  padding: 0 !important;
}

.ass-page .ass__toolbar .col:last-child,
.ass-page .ass__toolbar [class*='col-']:last-child {
  margin-left: auto;
}

.ass-page .ass__toolbar .p-button {
  border-radius: 10px;
  font-weight: 600;
  min-height: 2.5rem;
}

.ass-page .ass__toolbar .p-button-success,
.ass-page .ass__toolbar .p-button.p-button-success {
  box-shadow: 0 4px 14px rgba(34, 197, 94, 0.2);
}

/* Hero */
.ass-page .ass__hero {
  order: -10;
  display: flex;
  flex-wrap: wrap;
  align-items: flex-start;
  justify-content: space-between;
  gap: 1rem;
  width: 100%;
  margin-bottom: 1.25rem;
  padding: 1.35rem 1.5rem;
  border-radius: var(--ass-radius);
  background: linear-gradient(135deg, #4557a3 0%, #5b6fd6 55%, #7c8ce8 100%);
  color: #fff;
  box-shadow: 0 12px 40px rgba(69, 87, 163, 0.25);
}

.ass-page .ass__hero-main {
  flex: 1 1 240px;
  min-width: 0;
}

.ass-page .ass__eyebrow {
  display: block;
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  opacity: 0.85;
  margin-bottom: 0.35rem;
}

.ass-page .ass__hero h1 {
  margin: 0 0 0.4rem;
  font-size: clamp(1.2rem, 2.5vw, 1.55rem);
  font-weight: 800;
  line-height: 1.25;
}

.ass-page .ass__hero-sub {
  margin: 0;
  font-size: 0.92rem;
  opacity: 0.92;
  line-height: 1.5;
}

.ass-page .ass__hero-meta {
  flex: 0 0 auto;
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  align-items: center;
}

.ass-page .ass__chip {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  padding: 0.45rem 0.85rem;
  border-radius: 999px;
  font-size: 0.78rem;
  font-weight: 700;
  white-space: nowrap;
  background: rgba(255, 255, 255, 0.16);
  border: 1px solid rgba(255, 255, 255, 0.28);
  color: #fff;
}

.ass-page .ass__chip i {
  font-size: 0.82rem;
  opacity: 0.9;
}

/* Liste kartı */
.ass-page .ass__list-card {
  width: 100%;
  margin-bottom: 1.25rem;
  background: var(--ass-surface);
  border: 1px solid var(--ass-border);
  border-radius: var(--ass-radius);
  box-shadow: var(--ass-shadow);
  overflow: hidden;
}

.ass-page .ass__list-card > .form-container,
.ass-page .ass__list-card .form-container {
  padding: 0 !important;
  margin: 0 !important;
  border: none !important;
  box-shadow: none !important;
  background: transparent !important;
}

.ass-page .ass__list-head {
  display: flex;
  align-items: center;
  gap: 0.85rem;
  padding: 1.1rem 1.25rem;
  border-bottom: 1px solid var(--ass-border);
  background: linear-gradient(180deg, #f8fafc 0%, #fff 100%);
}

.ass-page .ass__list-head-icon {
  flex: 0 0 auto;
  width: 2.5rem;
  height: 2.5rem;
  border-radius: 12px;
  display: grid;
  place-items: center;
  background: #eef2ff;
  color: var(--ass-primary);
  font-size: 1rem;
}

.ass-page .ass__list-head h2 {
  margin: 0 0 0.15rem;
  font-size: 1.05rem;
  font-weight: 800;
  color: var(--ass-text);
}

.ass-page .ass__list-head p {
  margin: 0;
  font-size: 0.82rem;
  color: var(--ass-label);
  line-height: 1.4;
}

/* Tablo */
.ass-page .ass__inventory {
  padding: 0;
}

.ass-page .ass-table-wrap {
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
}

.ass-page .ass-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.88rem;
}

.ass-page .ass-table thead {
  background: var(--ass-soft);
  border-bottom: 2px solid var(--ass-border);
}

.ass-page .ass-table th {
  padding: 0.85rem 1.15rem;
  text-align: left;
  font-size: 0.68rem;
  font-weight: 800;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--ass-label);
  white-space: nowrap;
}

.ass-page .ass-table th.ass-table__qty,
.ass-page .ass-table td.ass-table__qty {
  text-align: right;
  width: 7rem;
}

.ass-page .ass-table th.ass-table__num,
.ass-page .ass-table td.ass-table__num {
  width: 3.25rem;
  text-align: center;
  color: var(--ass-muted);
  font-weight: 700;
  font-size: 0.78rem;
}

.ass-page .ass-table tbody {
  counter-reset: ass-row;
}

.ass-page .ass-table tbody .ass-table__num::before {
  counter-increment: ass-row;
  content: counter(ass-row);
}

.ass-page .ass-table__row {
  border-bottom: 1px solid #f1f5f9;
  transition: background 0.12s ease;
}

.ass-page .ass-table__row:hover {
  background: #f8fafc;
}

.ass-page .ass-table__row:last-child {
  border-bottom: none;
}

.ass-page .ass-table td {
  padding: 0.9rem 1.15rem;
  vertical-align: middle;
}

.ass-page .ass-table__link {
  display: inline-flex;
  align-items: flex-start;
  gap: 0.55rem;
  max-width: 100%;
  text-decoration: none;
  color: var(--ass-primary);
  font-weight: 700;
  line-height: 1.45;
  transition: color 0.12s ease;
}

.ass-page .ass-table__link:hover {
  color: var(--ass-accent);
}

.ass-page .ass-table__link-icon {
  flex: 0 0 auto;
  width: 1.75rem;
  height: 1.75rem;
  margin-top: 0.05rem;
  border-radius: 8px;
  display: grid;
  place-items: center;
  background: #eef2ff;
  color: var(--ass-primary);
  font-size: 0.78rem;
}

.ass-page .ass-table__link-text {
  flex: 1 1 auto;
  min-width: 0;
  word-break: break-word;
}

.ass-page .ass-table__link-arrow {
  flex: 0 0 auto;
  margin-top: 0.2rem;
  font-size: 0.68rem;
  opacity: 0;
  transform: translateX(-2px);
  transition: opacity 0.12s ease, transform 0.12s ease;
}

.ass-page .ass-table__link:hover .ass-table__link-arrow {
  opacity: 0.7;
  transform: translateX(0);
}

.ass-page .ass-qty-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 2.5rem;
  padding: 0.35rem 0.65rem;
  border-radius: 999px;
  background: #eef2ff;
  color: var(--ass-primary);
  font-size: 0.86rem;
  font-weight: 800;
  line-height: 1;
}

.ass-page .ass__empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 0.65rem;
  padding: 3rem 1.5rem;
  text-align: center;
  color: var(--ass-muted);
}

.ass-page .ass__empty i {
  font-size: 2rem;
  opacity: 0.55;
}

.ass-page .ass__empty p {
  margin: 0;
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--ass-label);
}

/* Eski loop/grid kalıntılarını gizle */
.ass-page .ass__list-card .loop,
.ass-page .ass__list-card .grid.ass__legacy-row {
  display: none !important;
}

@media (max-width: 767px) {
  .ass-page .ass__hero {
    padding: 1.1rem 1.15rem;
  }

  .ass-page .ass-table thead {
    display: none;
  }

  .ass-page .ass-table,
  .ass-page .ass-table tbody,
  .ass-page .ass-table tr,
  .ass-page .ass-table td {
    display: block;
    width: 100%;
  }

  .ass-page .ass-table__row {
    padding: 0.85rem 1rem;
    border-bottom: 1px solid var(--ass-border);
  }

  .ass-page .ass-table__row:hover {
    background: #fff;
  }

  .ass-page .ass-table td {
    padding: 0.25rem 0;
    text-align: left !important;
    width: 100% !important;
  }

  .ass-page .ass-table td.ass-table__num {
    display: none;
  }

  .ass-page .ass-table td.ass-table__qty {
    margin-top: 0.35rem;
  }

  .ass-page .ass-table td::before {
    content: attr(data-label);
    display: block;
    font-size: 0.64rem;
    font-weight: 800;
    letter-spacing: 0.05em;
    text-transform: uppercase;
    color: var(--ass-muted);
    margin-bottom: 0.2rem;
  }

  .ass-page .ass-table td.ass-table__name::before {
    display: none;
  }
}

@media print {
  .ass-page {
    background: #fff;
    padding: 0;
  }

  .ass-page .ass__toolbar {
    display: none !important;
  }

  .ass-page .ass__hero {
    box-shadow: none;
    border-radius: 0;
    print-color-adjust: exact;
    -webkit-print-color-adjust: exact;
  }

  .ass-page .ass__list-card {
    box-shadow: none;
    border: 1px solid #ddd;
  }

  .ass-page .ass-table__link {
    color: #000;
  }

  .ass-page .ass-table__link-arrow {
    display: none;
  }
}

/* Performans Değerlendirme Formu — Tüm Sonuçlar */

.ass-page .pdft-hero .ass__hero-meta {
  flex-wrap: wrap;
  justify-content: flex-end;
}

.ass-page .pdft-chip--score {
  background: rgba(255, 255, 255, 0.18) !important;
  border-color: rgba(255, 255, 255, 0.35) !important;
  color: #fff !important;
}

/* Filtre kartı */
.ass-page .pdft-filter-card {
  position: relative;
  z-index: 30;
  width: 100%;
  margin-bottom: 1.1rem;
  padding: 0;
  background: var(--ass-surface, #fff);
  border: 1px solid var(--ass-border, #e2e8f0);
  border-radius: var(--ass-radius, 16px);
  box-shadow: var(--ass-shadow, 0 4px 24px rgba(69, 87, 163, 0.08));
  overflow: visible;
}

.ass-page .pdft-filter-card::before {
  content: '';
  display: block;
  height: 3px;
  background: linear-gradient(90deg, #4557a3 0%, #5b6fd6 100%);
}

.ass-page .pdft-filter-grid,
.ass-page .pdft-filter-grid.grid,
.ass-page .pdft-filter-grid.row {
  display: flex !important;
  flex-wrap: wrap;
  align-items: flex-end;
  gap: 0.75rem 1rem;
  margin: 0 !important;
  padding: 0.95rem 1.1rem !important;
  background: transparent !important;
  border: none !important;
  overflow: visible !important;
}

.ass-page .pdft-filter-grid > .column,
.ass-page .pdft-filter-grid > .col,
.ass-page .pdft-filter-grid [class*='col-'] {
  flex: 1 1 200px;
  min-width: 0;
  padding: 0 !important;
  width: auto !important;
  max-width: 100% !important;
}

.ass-page .pdft-filter-grid .form-container {
  position: relative;
  z-index: 40;
  margin: 0 !important;
  padding: 0 !important;
  border: none !important;
  background: transparent !important;
  box-shadow: none !important;
  overflow: visible !important;
}

.ass-page .pdft-filter-grid .p-field,
.ass-page .pdft-filter-grid .field,
.ass-page .pdft-filter-grid .form-group {
  overflow: visible !important;
}

.ass-page .pdft-filter-grid .p-dropdown {
  width: 100% !important;
  min-width: 14rem;
  border-radius: 10px !important;
  border-color: #c7d2fe !important;
}

.ass-page .pdft-filter-grid .p-dropdown-panel,
.ass-page .pdft-filter-card .p-dropdown-panel,
.ass-page .pdft-filter-grid .p-dropdown-items-wrapper {
  z-index: 9999 !important;
}

.ass-page .pdft-filter-grid .p-dropdown.p-dropdown-open {
  z-index: 50;
  position: relative;
}

.ass-page .pdft-filter-grid label,
.ass-page .pdft-filter-grid .p-field label {
  color: #64748b !important;
  font-size: 0.72rem !important;
  font-weight: 700 !important;
  margin-bottom: 0.25rem !important;
}

/* Sonuç tablosu kartı */
.ass-page .pdft-results-card {
  width: 100%;
  margin-bottom: 1.25rem;
  padding: 0;
  background: var(--ass-surface, #fff);
  border: 1px solid var(--ass-border, #e2e8f0);
  border-radius: var(--ass-radius, 16px);
  box-shadow: var(--ass-shadow, 0 4px 24px rgba(69, 87, 163, 0.08));
  overflow: visible;
}

.ass-page .pdft-results-card::before {
  content: '';
  display: block;
  height: 4px;
  background: linear-gradient(90deg, #4557a3 0%, #5b6fd6 55%, #7c8ce8 100%);
}

.ass-page .pdft-results-form,
.ass-page .pdft-results-card .form-container {
  padding: 0.5rem 0.85rem 1rem !important;
  margin: 0 !important;
  border: none !important;
  background: transparent !important;
  box-shadow: none !important;
}

.ass-page .pdft-form-array {
  margin: 0 !important;
  padding: 0 !important;
}

.ass-page .pdft-form-group {
  margin: 0 !important;
  padding: 0 !important;
  border: none !important;
  background: transparent !important;
}

/* Üst bilgi satırı */
.ass-page .pdft-matrix-meta,
.ass-page .pdft-matrix-meta.grid,
.ass-page .pdft-matrix-meta.row {
  display: flex !important;
  flex-wrap: wrap;
  gap: 0.35rem 1rem;
  margin: 0 0 0.75rem !important;
  padding: 0.65rem 0.75rem !important;
  border-radius: 10px;
  background: #f8fafc !important;
  border: 1px solid #e8edf5 !important;
}

.ass-page .pdft-matrix-meta > .column,
.ass-page .pdft-matrix-meta > .col,
.ass-page .pdft-matrix-meta [class*='col-'] {
  flex: 1 1 180px;
  min-width: 0;
  padding: 0 !important;
  width: auto !important;
}

.ass-page .pdft-matrix-meta .label {
  color: #475569 !important;
  font-size: 0.84rem !important;
  font-weight: 600 !important;
}

/* Tablo başlık satırı */
.ass-page .pdft-matrix-header,
.ass-page .pdft-matrix-header.grid,
.ass-page .pdft-matrix-header.row {
  margin: 0 0 0.35rem !important;
  padding: 0 !important;
  background: transparent !important;
  border: none !important;
}

.ass-page .pdft-matrix-header > .column,
.ass-page .pdft-matrix-header > .col,
.ass-page .pdft-matrix-header [class*='col-'] {
  padding: 0 !important;
}

.ass-page .pdft-matrix-header .label {
  display: flex;
  align-items: center;
  min-height: 2.5rem;
  margin: 0 !important;
  padding: 0.55rem 0.75rem !important;
  border-radius: 10px;
  background: linear-gradient(135deg, #4557a3 0%, #5b6fd6 100%) !important;
  color: #fff !important;
  font-size: 0.78rem !important;
  font-weight: 800 !important;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

/* Tablo gövdesi — satır bazlı hizalama (kriter | puan | ortalama) */
.ass-page .pdft-matrix-body,
.ass-page .pdft-matrix-body.grid,
.ass-page .pdft-matrix-body.row {
  display: flex !important;
  flex-direction: column !important;
  flex-wrap: nowrap !important;
  gap: 0.35rem;
  margin: 0 !important;
  padding: 0 !important;
  background: transparent !important;
  border: none !important;
}

.ass-page .pdft-matrix-rows-loop,
.ass-page .pdft-matrix-body > .pdft-matrix-rows-loop {
  display: flex !important;
  flex-direction: column !important;
  gap: 0.35rem;
  margin: 0 !important;
  padding: 0 !important;
  width: 100%;
}

.ass-page .pdft-matrix-row,
.ass-page .pdft-matrix-row.grid,
.ass-page .pdft-matrix-row.row {
  display: grid !important;
  grid-template-columns: minmax(280px, 34%) 1fr 88px;
  gap: 0.5rem;
  align-items: stretch;
  margin: 0 !important;
  padding: 0 !important;
  width: 100% !important;
  background: transparent !important;
  border: none !important;
}

.ass-page .pdft-matrix-footer,
.ass-page .pdft-matrix-footer.grid,
.ass-page .pdft-matrix-footer.row {
  display: grid !important;
  grid-template-columns: minmax(280px, 34%) 1fr 88px;
  gap: 0.5rem;
  align-items: center;
  margin: 0.15rem 0 0 !important;
  padding: 0 !important;
  width: 100% !important;
  background: transparent !important;
  border: none !important;
}

.ass-page .pdft-matrix-row > .column,
.ass-page .pdft-matrix-row > .col,
.ass-page .pdft-matrix-footer > .column,
.ass-page .pdft-matrix-footer > .col,
.ass-page .pdft-row-criterion,
.ass-page .pdft-row-scores,
.ass-page .pdft-row-avg {
  padding: 0 !important;
  min-width: 0;
  align-self: stretch;
}

.ass-page .pdft-row-scores {
  overflow-x: auto;
  overflow-y: visible;
  -webkit-overflow-scrolling: touch;
}

.ass-page .pdft-footer-spacer {
  min-height: 0;
}

/* Eski üç sütun düzeni (geri uyumluluk) */
.ass-page .pdft-matrix-body > .column,
.ass-page .pdft-matrix-body > .col,
.ass-page .pdft-matrix-body [class*='col-'] {
  padding: 0 !important;
  min-width: 0;
  align-self: flex-start;
}

.ass-page .pdft-criteria-col,
.ass-page .pdft-matrix-body > .column:first-child,
.ass-page .pdft-matrix-body > .col:first-child {
  flex: 0 0 34% !important;
  width: 34% !important;
  min-width: 280px !important;
  max-width: 420px !important;
}

.ass-page .pdft-scroll-col,
.ass-page .pdft-matrix-body .col-scroll {
  flex: 1 1 auto !important;
  width: auto !important;
  min-width: 0 !important;
  max-width: none !important;
  overflow-x: auto;
  overflow-y: visible;
  -webkit-overflow-scrolling: touch;
  padding-bottom: 0.25rem !important;
}

.ass-page .pdft-avg-col,
.ass-page .pdft-matrix-body > .column:last-child,
.ass-page .pdft-matrix-body > .col:last-child {
  flex: 0 0 88px !important;
  width: 88px !important;
  min-width: 88px !important;
  max-width: 104px !important;
  background: transparent !important;
}

.ass-page .pdft-avg-col.column,
.ass-page .pdft-avg-col[class*='col-'] {
  background-color: transparent !important;
  background-image: none !important;
}

/* Soru döngüleri — sütunlar arası dikey hizalama */
.ass-page .pdft-matrix-body .pdft-question-loop,
.ass-page .pdft-matrix-body .pdft-matrix-loop.pdft-question-loop {
  display: flex !important;
  flex-direction: column !important;
  gap: 0.35rem;
  margin: 0 !important;
  padding: 0 !important;
}

.ass-page .pdft-criteria-col .pdft-hidden-field,
.ass-page .pdft-criteria-col .input-hidden,
.ass-page .pdft-criteria-col [class*='input-hidden'],
.ass-page .pdft-row-criterion .pdft-hidden-field,
.ass-page .pdft-row-criterion .input-hidden,
.ass-page .pdft-row-criterion [class*='input-hidden'] {
  display: none !important;
  width: 0 !important;
  height: 0 !important;
  margin: 0 !important;
  padding: 0 !important;
  overflow: hidden !important;
  visibility: hidden !important;
}

/* Kriter satırları */
.ass-page .pdft-criterion,
.ass-page .pdft-criterion.label,
.ass-page .pdft-criterion.pdft-score-chip {
  display: flex !important;
  align-items: center;
  justify-content: flex-start;
  width: 100% !important;
  min-width: 0 !important;
  max-width: 100% !important;
  height: auto !important;
  min-height: 2.75rem;
  margin: 0 !important;
  padding: 0.55rem 0.75rem !important;
  border-radius: 8px;
  background: #f8fafc;
  border: 1px solid #eef2f7;
  color: #334155 !important;
  font-size: 0.86rem !important;
  font-weight: 600 !important;
  line-height: 1.35 !important;
  white-space: normal !important;
  word-break: break-word;
